// Ambil header Set-Cookie dari response dan simpan sebagai string 'nama=nilai'
const headers = $input.first().json.headers;
let setCookie = headers['set-cookie'] || headers['Set-Cookie'];
if (Array.isArray(setCookie)) setCookie = setCookie[0];
if (!setCookie) throw new Error('Set-Cookie header tidak ditemukan, cek response headers manual.');
const cookiePair = setCookie.split(';')[0]; // contoh: ASPSESSIONIDAGSRDDAR=XXXXXXXX
return [{ json: { cookie: cookiePair } }];

// Bawa cookie dari node sebelumnya + set halaman awal = 1
// Reset accumulator supaya run baru mulai bersih
const staticData = $getWorkflowStaticData('global');
staticData.allRows = [];
const cookie = $('Extract Cookie String').first().json.cookie;
return [{ json: { cookie, page: 1 } }];

// Parsing HTML sederhana pakai regex (tanpa dependency Cheerio) untuk baris tabel hasil.
const html = $input.first().json.data || $input.first().json.body || $input.first().json;
const htmlStr = typeof html === 'string' ? html : JSON.stringify(html);

// Versi teks polos (tag di-strip) supaya deteksi paging tahan terhadap tag <b> dsb di antara angka
const textOnly = htmlStr.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ');
const pagingMatch = textOnly.match(/(\d+)\s*records found page\s*(\d+)\s*of\s*(\d+)/i);
const totalPages = pagingMatch ? parseInt(pagingMatch[3]) : 1;
const currentPage = pagingMatch ? parseInt(pagingMatch[2]) : $('Initialize Page to 1').first().json.page;

// Ambil setiap baris <tr>...</tr> dari body tabel (skip header)
const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;
const rows = [...htmlStr.matchAll(rowRegex)].map(m => m[1]);

const results = [];
for (const row of rows) {
  const accountMatch = row.match(/Account=([A-Z0-9\-]+)/i);
  if (!accountMatch) continue; // skip baris header / non-data

  const cells = [...row.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)]
    .map(c => c[1].replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim());

  const nsrNoCell = cells.find(c => /^\d{5,7}$/.test(c));
  const nameMatch = row.match(/Account=[^"'>]+["'][^>]*>\s*([^<]+?)\s*</i);
  const name = nameMatch ? nameMatch[1].trim() : (cells.find(c => c.length > 3 && !/^\d+$/.test(c) && !/^(DR|MALE|FEMALE)$/i.test(c)) || '');
  const gender = cells.find(c => /^(Male|Female)$/i.test(c)) || '';

  results.push({
    nsr_no: nsrNoCell || '',
    name,
    gender,
    specialty: 'CARDIOLOGY',
    account_id: accountMatch[1]
  });
}

const cookie = $('Initialize Page to 1').first().json.cookie;
const rowsWithMeta = results.map(r => ({ ...r, cookie, currentPage, totalPages }));

// Kumpulkan ke accumulator global, diproses SEKALI SAJA setelah semua halaman habis
const staticData = $getWorkflowStaticData('global');
if (!staticData.allRows) staticData.allRows = [];
staticData.allRows.push(...rowsWithMeta);

return rowsWithMeta.map(r => ({ json: r }));

const html = $input.first().json.data || $input.first().json.body || $input.first().json;
const htmlStr = typeof html === 'string' ? html : JSON.stringify(html);

// --- Grad Year: ambil 'Year of award' dari baris Basic Degree (bukan Specialist Degree) ---
const basicIdx = htmlStr.search(/Basic\s*Degree/i);
const specialistIdx = htmlStr.search(/Specialist\s*Degree/i);
let gradYear = '';
if (basicIdx !== -1) {
  const end = (specialistIdx !== -1 && specialistIdx > basicIdx) ? specialistIdx : basicIdx + 2000;
  const segment = htmlStr.slice(basicIdx, end);
  const yearMatch = segment.match(/\b(19|20)\d{2}\b/);
  if (yearMatch) gradYear = yearMatch[0];
}

// --- Specialty 1 & 2: ambil dari baris 'Specialty' di Personal Data, pisah pakai karakter '|' ---
const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;
const rows = [...htmlStr.matchAll(rowRegex)].map(m => m[1]);
let specialtyRaw = '';
for (const row of rows) {
  if (/>\s*Specialty\s*</i.test(row)) {
    const cells = [...row.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)]
      .map(c => c[1].replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim());
    specialtyRaw = cells[cells.length - 1] || '';
    break;
  }
}
const specialtyParts = specialtyRaw.split('|').map(s => s.trim()).filter(Boolean);

const prev = $('Process Each Doctor Batch').item.json;
return [{
  json: {
    Name: prev.name,
    License: prev.nsr_no,
    'Specialty 1': specialtyParts[0] || '',
    'Specialty 2': specialtyParts[1] || '',
    Gender: prev.gender,
    'Grad Year': gradYear
  }
}];

// Setelah semua baris di halaman ini selesai diproses satu per satu (loop 7-11 balik ke sini),
// node ini menentukan apakah lanjut ke halaman berikutnya.
const rowsThisPage = $('Parse HTML Table Rows').all();
const currentPage = rowsThisPage.length ? rowsThisPage[0].json.currentPage : 1;
const totalPages = rowsThisPage.length ? rowsThisPage[0].json.totalPages : 1;
const cookie = $('Initialize Page to 1').first().json.cookie;
const hasMore = currentPage < totalPages;
return [{ json: { hasMore, page: currentPage + 1, cookie } }];

// Dipanggil SEKALI setelah semua 24 halaman selesai di-paginate.
// Ambil seluruh accumulator dokter (~461 item), lalu reset accumulator.
const staticData = $getWorkflowStaticData('global');
const allRows = staticData.allRows || [];
staticData.allRows = [];
return allRows.map(r => ({ json: r }));
